#include <bits/stdc++.h>
using namespace std;
int hp(const vector<int>& rows){int n=rows.size(),N=1<<n;vector<unsigned char>d(N*n);for(int u=0;u<n;u++)d[(1<<u)*n+u]=1;for(int S=1;S<N;S++)for(int u=0;u<n;u++){int x=d[S*n+u];if(!x)continue;int left=rows[u]&~S;while(left){int v=__builtin_ctz(left),b=1<<v;left^=b;d[(S|b)*n+v]=(d[(S|b)*n+v]+x)&7;}}int out=0;for(int u=0;u<n;u++)out+=d[(N-1)*n+u];return out&7;}
int main(){for(int n=2;n<=5;n++){int N=1<<n,fail=0,vertex_bad=0;for(int code=0;code<(1<<(n*(n-1)/2));code++){vector<int>Q(n);int b=0;for(int u=0;u<n;u++)for(int v=u+1;v<n;v++,b++)Q[(code>>b&1)?u:v]|=1<<((code>>b&1)?v:u);vector<int>T(2*n);for(int i=0;i<n;i++){T[2*i]|=1<<(2*i+1);for(int j=0;j<n;j++)if(Q[i]>>j&1){T[2*i]|=3<<(2*j);T[2*i+1]|=3<<(2*j);}}vector<int>cache(N*N,-1);auto get=[&](int a,int c){int&h=cache[a*N+c];if(h>=0)return h;auto R=T;R.push_back(1<<(2*n+1));R.push_back(0);for(int u=0;u<2*n;u++){if(a>>(u/2)&1)R[u]|=1<<(2*n);else R[2*n]|=1<<u;if(c>>(u/2)&1)R[u]|=1<<(2*n+1);else R[2*n+1]|=1<<u;}return h=hp(R);};auto d=[&](int a,int c){return get(a,c)-get((N-1)^c,(N-1)^a);};int all=0;for(int v=0;v<n;v++){int av=1<<v,L=0;for(int u=0;u<n;u++)if(u!=v){int au=1<<u;L+=d(au,av)-d(au,0)-d(0,av)+d(0,0);if(Q[v]>>u&1)L+=d(au|av,av)-d(au,av)-d(av,av)+d(0,av)-d(au|av,0)+d(au,0)+d(av,0)-d(0,0);}all+=L;if((L%4+4)%4)vertex_bad++;}if((all%8+8)%8!=(4*n)%8){fail++;cout<<"FAIL "<<n<<" "<<code<<" "<<((all%8+8)%8)<<endl;break;}}cout<<"n="<<n<<" failures="<<fail<<" individual_not_div4="<<vertex_bad<<endl;if(fail||vertex_bad)return 1;}}
